/* vNN.xx, UI REDESIGN ui5q2e (his #50, from the AAA judge of the raid pause shot): ONE BUTTON SIZE IN THE PAUSE ROW. FEEDBACK (v24.50)
   came after the pause row was set to 48px buttons with 16px labels (ui5q1f), so it was the one small button in the row, clearly
   smaller at 4K. It matches SETTINGS and ABANDON RUN now. */
#root #pausebox #fbbtn{ min-height:48px; padding:0 26px !important; font-size:16px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; }
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2e): FEEDBACK in the raid pause row is the same size as SETTINGS (label size and button height)',
 run:function(){
   var f=document.getElementById('fbbtn'), s=document.getElementById('pausesetbtn');
   if(!f||!s) return 'SKIP: no FEEDBACK or SETTINGS in the pause box';
   var cf=getComputedStyle(f), cs=getComputedStyle(s), bad=[];
   if(cf.fontSize!==cs.fontSize) bad.push('FEEDBACK is '+cf.fontSize+' against SETTINGS '+cs.fontSize);
   if(cf.minHeight!==cs.minHeight) bad.push('FEEDBACK is '+cf.minHeight+' high against SETTINGS '+cs.minHeight);
   if(cf.fontWeight!==cs.fontWeight) bad.push('FEEDBACK weight '+cf.fontWeight+' against '+cs.fontWeight);
   return bad.length?bad.join('; '):null; }},
